begin;
create table public.bitacora_fondos (
 id uuid primary key default gen_random_uuid(),
 fund text not null unique check(fund in ('FASP','FOFISP')),
 version integer not null default 1 check(version>0),
 data jsonb not null,
 date_keys jsonb not null,
 delivery_keys jsonb not null,
 updated_at timestamptz not null default now()
);
alter table public.bitacora_fondos enable row level security;
create policy fondos_lectura on public.bitacora_fondos for select to authenticated
 using ((select private.rol_actual()) in ('admin','capacitacion'));
revoke all on public.bitacora_fondos from anon,authenticated;
grant select on public.bitacora_fondos to authenticated;
create trigger auditar_bitacora_fondos after update on public.bitacora_fondos
 for each row execute function private.auditar();

create function public.actualizar_bitacora_fondo(fondo text,revision integer,seccion text,celda text,valor jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare doc public.bitacora_fondos; parsed date; raw text;
begin
 if coalesce(private.rol_actual(),'') not in ('admin','capacitacion') then
  raise exception 'Sin permiso para modificar la bitácora.' using errcode='42501';
 end if;
 select * into doc from public.bitacora_fondos where fund=fondo for update;
 if not found then raise exception 'Fondo no encontrado.' using errcode='22023'; end if;
 if doc.version<>revision then raise exception 'La bitácora cambió. Actualice antes de guardar.'; end if;
 if seccion not in ('values','receipts') or not (doc.data->'values' ? celda) then
  raise exception 'Celda no editable.' using errcode='22023';
 end if;
 valor:=coalesce(valor,'null'::jsonb);
 if jsonb_typeof(valor) not in ('string','number','null') or length(valor::text)>30002 then
  raise exception 'Contenido no válido.' using errcode='22023';
 end if;
 raw:=valor #>> '{}';
 if jsonb_typeof(valor)='string' and length(raw)>5000 then
  raise exception 'Contenido demasiado largo.' using errcode='22023';
 end if;
 if seccion='receipts' then
  if not(doc.delivery_keys ? celda) then raise exception 'Entrega UMS no válida.' using errcode='22023'; end if;
  if raw is not null then
   if raw !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.' using errcode='22023'; end if;
   parsed:=raw::date;
   if parsed>(now() at time zone 'America/Mexico_City')::date then
    raise exception 'La recepción no puede ser futura.' using errcode='22023';
   end if;
  end if;
 elsif doc.date_keys ? celda and raw is not null and upper(trim(raw)) not in ('N/A','ENTREGADO') then
  if raw !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'Fecha no válida.' using errcode='22023'; end if;
  parsed:=raw::date;
 end if;
 update public.bitacora_fondos set data=jsonb_set(data,array[seccion,celda],valor,true),
  version=version+1,updated_at=now() where id=doc.id returning * into doc;
 return jsonb_build_object('fund',doc.fund,'version',doc.version,'data',doc.data);
end $$;
revoke all on function public.actualizar_bitacora_fondo(text,integer,text,text,jsonb) from public,anon;
grant execute on function public.actualizar_bitacora_fondo(text,integer,text,text,jsonb) to authenticated;

